--
-- Table structure for table `solder_paste`
--

DROP TABLE IF EXISTS solder_paste;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE solder_paste (
  id int NOT NULL AUTO_INCREMENT,
  did varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Document Identification - Requerido al registrar',
  lot_number varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Número de lote (posición 1 del QR)',
  part_number varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Número de parte (posición 2 del QR)',
  lot_serial varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Serial del lote (posición 5 del QR)',
  smt_location varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ubicación SMT detectada (SMT, SMT2, SMT3, SMT4)',
  manufacture_date date NOT NULL COMMENT 'Fecha de fabricación (posición 4 del QR)',
  expiration_date date NOT NULL COMMENT 'Fecha de expiración (posición 3 del QR)',
  fridge_in_datetime datetime DEFAULT NULL COMMENT 'Escaneo 1: Entrada al refrigerador',
  fridge_out_datetime datetime DEFAULT NULL COMMENT 'Escaneo 2: Salida del refrigerador',
  mixing_start_datetime datetime DEFAULT NULL COMMENT 'Escaneo 3: Inicio de mezclado',
  viscosity_value decimal(5,2) DEFAULT NULL COMMENT 'Escaneo 4: Valor de viscosidad (150-180)',
  viscosity_datetime datetime DEFAULT NULL COMMENT 'Escaneo 4: Fecha/hora registro viscosidad',
  opened_datetime datetime DEFAULT NULL COMMENT 'Escaneo 5: Apertura del contenedor',
  removed_datetime datetime DEFAULT NULL COMMENT 'Escaneo 6: Retiro final',
  fridge_in_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que registró entrada al refrigerador',
  fridge_out_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que registró salida del refrigerador',
  mixing_start_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que inició el mezclado',
  viscosity_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que registró la viscosidad',
  opened_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que abrió el contenedor',
  removed_user varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que retiró la pasta',
  `status` enum('in_fridge','out_fridge','mixing','viscosity_ok','opened','removed','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_fridge',
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY unique_lot_serial (lot_number,lot_serial),
  KEY idx_lot_number (lot_number),
  KEY idx_part_number (part_number),
  KEY idx_status (`status`),
  KEY idx_expiration (expiration_date),
  KEY idx_did (did),
  KEY idx_smt_location (smt_location)
) ENGINE=InnoDB AUTO_INCREMENT=285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

